INSERT INTO f360.shopify_products (target_id, shopify_product_id)
SELECT DISTINCT (SELECT id FROM f360.sales_targets WHERE key = 'shopify_mx' AND kind = 'shopify'), shopify_product_id::bigint FROM shopify_catalog_in
ON CONFLICT DO NOTHING;
INSERT INTO f360.shopify_variants (target_id, shopify_variant_id, shopify_product_id, inventory_item_id, handle, product_title, color, size, sku, woo_product_id, woo_variation_id, seen_at)
SELECT (SELECT id FROM f360.sales_targets WHERE key = 'shopify_mx' AND kind = 'shopify'), v.*, now() FROM shopify_catalog_in v
ON CONFLICT (target_id, shopify_variant_id) DO UPDATE SET shopify_product_id = EXCLUDED.shopify_product_id, inventory_item_id = EXCLUDED.inventory_item_id,
  handle = EXCLUDED.handle, product_title = EXCLUDED.product_title, color = EXCLUDED.color, size = EXCLUDED.size, sku = EXCLUDED.sku,
  woo_product_id = EXCLUDED.woo_product_id, woo_variation_id = EXCLUDED.woo_variation_id, seen_at = now();

CREATE TEMP TABLE shopify_link_result ON COMMIT DROP AS SELECT f360.shopify_link_variants('shopify_mx', 'woo_production') AS r;
DO $$ DECLARE r jsonb := (SELECT r FROM shopify_link_result); BEGIN
  IF (SELECT count(*) FROM f360.shopify_variants s JOIN f360.sales_targets t ON t.id = s.target_id WHERE t.key = 'shopify_mx') < 1200 THEN RAISE EXCEPTION 'POST: catálogo incompleto'; END IF;
  IF (r->>'ligadas')::int < 900 THEN RAISE EXCEPTION 'POST: pocas ligas (%)', r->>'ligadas'; END IF;
  IF EXISTS (SELECT l.variant_id FROM f360.woo_variant_links l JOIN f360.sales_targets t ON t.id = l.target_id WHERE t.key = 'shopify_mx' GROUP BY l.variant_id HAVING count(*) > 1) THEN RAISE EXCEPTION 'POST: par ligado dos veces'; END IF;
  IF EXISTS (SELECT 1 FROM f360.woo_variant_links l JOIN f360.sales_targets t ON t.id = l.target_id JOIN f360.shopify_variants s ON s.target_id = t.id AND s.link_id = l.woo_variation_id
              JOIN f360.product_variants v ON v.id = l.variant_id JOIN f360.product_colors c ON c.id = v.color_id
             WHERE t.key = 'shopify_mx' AND (f360.shopify_norm(c.name) <> f360.shopify_norm(s.color) OR v.size_label <> s.size)) THEN RAISE EXCEPTION 'POST: liga con otro color o talla'; END IF;
  IF (SELECT count(*) FROM f360.woo_variant_links l JOIN f360.sales_targets t ON t.id = l.target_id WHERE t.key = 'woo_production') <> 1302 THEN RAISE EXCEPTION 'POST: ligas Woo tocadas'; END IF;
  IF NOT EXISTS (SELECT 1 FROM f360.sales_targets WHERE key = 'shopify_mx' AND is_production AND NOT active AND orders_mode = 'on' AND stock_sync_mode = 'off') THEN RAISE EXCEPTION 'POST: canal'; END IF;
  IF has_table_privilege('authenticated', 'f360.shopify_variants', 'SELECT') OR has_function_privilege('anon', 'public.f360_shopify_localize(text, jsonb)', 'EXECUTE') THEN RAISE EXCEPTION 'POST: expuesto'; END IF;
END $$;
SELECT r - 'pendientes' AS liga, jsonb_array_length(r->'pendientes') AS colores_pendientes FROM shopify_link_result;
COMMIT;
